import React from 'react';
import { NavLink } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import '../cssStyles/Sidebar.css';

const Sidebar = ({ isOpen, toggleSidebar, userRole }) => {
  const { user } = useAuth();
  
  const menuItems = getMenuItems(userRole);
  
  return (
    <>
      {/* Overlay when sidebar is open (for mobile) */}
      {isOpen && <div className="sidebar-overlay" onClick={toggleSidebar}></div>}
      
      <aside className={`sidebar ${isOpen ? 'open' : 'closed'}`}>
        <div className="sidebar-header">
          <div className="user-info">
            <div className="user-avatar">
              {user?.avatar ? (
                <img 
                  src={user.avatar} 
                  alt={`${user.firstName} ${user.lastName}`}
                />
              ) : (
                <div className="avatar-placeholder">
                  {user?.firstName?.charAt(0)}{user?.lastName?.charAt(0)}
                </div>
              )}
            </div>
            <div className="user-details">
              <div className="user-name">{user?.firstName} {user?.lastName}</div>
              <div className="user-role">{userRole}</div>
            </div>
            <button className="sidebar-close-btn" onClick={toggleSidebar}>
              <i className="fas fa-times"></i>
            </button>
          </div>
        </div>
        
        <nav className="sidebar-nav">
          <ul className="nav flex-column">
            {menuItems.map((item, index) => (
              <React.Fragment key={item.path || index}>
                {item.header && (
                  <li className="nav-header">{item.header}</li>
                )}
                
                {item.path && (
                  <li className="nav-item">
                    <NavLink 
                      to={item.path} 
                      className={({ isActive }) => `nav-link ${isActive ? 'active' : ''}`}
                      onClick={toggleSidebar}
                    >
                      <i className={`nav-icon ${item.icon}`}></i>
                      <span className="nav-text">{item.label}</span>
                      {item.badge && <span className="nav-badge">{item.badge}</span>}
                    </NavLink>
                  </li>
                )}
                
                {item.divider && (
                  <li className="nav-divider"></li>
                )}
              </React.Fragment>
            ))}
          </ul>
        </nav>
        
        <div className="sidebar-footer">
          <div className="app-version">Smart City v1.0.0</div>
          <div className="app-copyright">© {new Date().getFullYear()}</div>
        </div>
      </aside>
    </>
  );
};

// Helper function to get menu items based on user role
const getMenuItems = (userRole) => {
  // ... (keep your existing getMenuItems implementation)
  // Return the appropriate menu items array
};

export default Sidebar;
